-- Additive testing release. Original imports and existing approval snapshots are retained.
CREATE TABLE erp_private.account_catalog (
 code text PRIMARY KEY CHECK(code ~ '^[0-9]{5}$'),name text NOT NULL,account_group text NOT NULL,
 route integer CHECK(route IN (1,2,3)),category_code text NOT NULL,statement text NOT NULL,
 tax_note text NOT NULL DEFAULT '',evidence text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',
 is_legacy boolean NOT NULL DEFAULT false,asset_class jsonb,catalog_version text NOT NULL,
 status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Draft','Active')),revision bigint NOT NULL DEFAULT 1,
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
