CREATE TABLE erp_private.accounting_policies (
 client_id uuid PRIMARY KEY REFERENCES erp_private.clients,inventory_method text NOT NULL CHECK(inventory_method IN ('Periodic','Perpetual')),
 notes text NOT NULL CHECK(length(btrim(notes))>=10),configured_by uuid NOT NULL REFERENCES erp_private.staff_members,
 revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE erp_private.workbook_rows ADD COLUMN account_code text REFERENCES erp_private.account_catalog,
 ADD COLUMN account_name text,ADD COLUMN catalog_version text,ADD COLUMN first_use_status text CHECK(first_use_status IN ('In use','Not yet in use')),
 ADD COLUMN first_use_date date,ADD COLUMN parent_row_id uuid REFERENCES erp_private.workbook_rows,
 ADD COLUMN is_split_parent boolean NOT NULL DEFAULT false;
CREATE INDEX workbook_rows_parent_idx ON erp_private.workbook_rows(parent_row_id) WHERE parent_row_id IS NOT NULL;
CREATE TABLE erp_private.sales_reconciliations (
 reconciliation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES erp_private.projects,
 review_type text NOT NULL CHECK(review_type IN ('Weekly','Monthly')),starts_on date NOT NULL,ends_on date NOT NULL CHECK(ends_on>=starts_on),
 inputs jsonb NOT NULL DEFAULT '{}',result jsonb NOT NULL DEFAULT '{}',source_fingerprint text,
 status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Submitted','Returned','Locked')),
 prepared_by uuid NOT NULL REFERENCES erp_private.staff_members,reviewed_by uuid REFERENCES erp_private.staff_members,
 review_note text,review_snapshot jsonb,revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(project_id,review_type,starts_on,ends_on)
);
CREATE INDEX sales_recon_project_idx ON erp_private.sales_reconciliations(project_id,ends_on);
CREATE TABLE erp_private.sales_review_versions (
 version_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reconciliation_id uuid NOT NULL REFERENCES erp_private.sales_reconciliations,
 project_id uuid NOT NULL REFERENCES erp_private.projects,snapshot jsonb NOT NULL,created_by uuid NOT NULL REFERENCES erp_private.staff_members,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sales_versions_project_idx ON erp_private.sales_review_versions(project_id,reconciliation_id);
ALTER TABLE erp_private.workbook_batches DROP CONSTRAINT IF EXISTS workbook_batches_dataset_check;
ALTER TABLE erp_private.workbook_batches ADD CONSTRAINT workbook_batches_dataset_check CHECK(dataset IN ('Sales','POS','Purchases','Expenditure','Non-eTIMS','Bank','General'));

CREATE OR REPLACE FUNCTION erp_private.workbook_row_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF (to_jsonb(NEW)-ARRAY['route','category_code','narration','asset_details','review_details','revision','updated_at','account_code','account_name','catalog_version','first_use_status','first_use_date','is_split_parent']) IS DISTINCT FROM
 (to_jsonb(OLD)-ARRAY['route','category_code','narration','asset_details','review_details','revision','updated_at','account_code','account_name','catalog_version','first_use_status','first_use_date','is_split_parent']) THEN RAISE EXCEPTION 'Imported source rows are immutable' USING ERRCODE='23514';END IF;
 IF OLD.is_split_parent THEN RAISE EXCEPTION 'Split source is retained unchanged' USING ERRCODE='23514';END IF;
 RETURN NEW;
END;$$;
CREATE FUNCTION erp_private.accounting_row_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE a erp_private.account_catalog;p erp_private.workbook_rows;
BEGIN
 IF NEW.account_code IS NOT NULL THEN
  SELECT * INTO a FROM erp_private.account_catalog WHERE code=NEW.account_code;
  IF a.status<>'Active' OR a.is_legacy OR a.route IS DISTINCT FROM NEW.route OR a.category_code IS DISTINCT FROM NEW.category_code THEN RAISE EXCEPTION 'Account and route do not match' USING ERRCODE='23514';END IF;
  NEW.account_name:=a.name;NEW.catalog_version:=a.catalog_version;
  IF NEW.route=3 AND (length(btrim(coalesce(NEW.asset_details,'')))=0 OR NEW.first_use_status IS NULL OR (NEW.first_use_status='In use' AND NEW.first_use_date IS NULL)) THEN RAISE EXCEPTION 'Asset description and first-use status required' USING ERRCODE='23514';END IF;
 END IF;
 IF TG_OP='INSERT' AND NEW.parent_row_id IS NOT NULL THEN
  SELECT * INTO p FROM erp_private.workbook_rows WHERE row_id=NEW.parent_row_id;
  IF p.parent_row_id IS NOT NULL OR NOT p.is_split_parent OR (NEW.batch_id,NEW.project_id,NEW.client_id,NEW.dataset,NEW.source_row) IS DISTINCT FROM (p.batch_id,p.project_id,p.client_id,p.dataset,p.source_row) OR NEW.raw_values IS DISTINCT FROM p.raw_values OR
  (NEW.normalized-ARRAY['amount','vat','gross','line_id','description']) IS DISTINCT FROM (p.normalized-ARRAY['amount','vat','gross','line_id','description']) THEN RAISE EXCEPTION 'Invalid allocation source link' USING ERRCODE='23514';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER accounting_guard BEFORE INSERT OR UPDATE ON erp_private.workbook_rows FOR EACH ROW EXECUTE FUNCTION erp_private.accounting_row_guard();
CREATE FUNCTION erp_private.split_totals_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE p erp_private.workbook_rows;n integer;net numeric;vat numeric;
BEGIN
 SELECT * INTO p FROM erp_private.workbook_rows WHERE row_id=coalesce(NEW.parent_row_id,NEW.row_id);
 IF p.is_split_parent THEN
  SELECT count(*),sum((normalized->>'amount')::numeric),sum(coalesce((normalized->>'vat')::numeric,0)) INTO n,net,vat FROM erp_private.workbook_rows WHERE parent_row_id=p.row_id;
  IF n<2 OR net IS DISTINCT FROM (p.normalized->>'amount')::numeric OR vat IS DISTINCT FROM coalesce((p.normalized->>'vat')::numeric,0) THEN RAISE EXCEPTION 'Split totals must equal original net and VAT' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;
END;$$;
CREATE CONSTRAINT TRIGGER split_totals AFTER INSERT OR UPDATE ON erp_private.workbook_rows DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION erp_private.split_totals_guard();
CREATE FUNCTION erp_private.accounting_control_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF TG_TABLE_NAME='account_catalog' THEN
  IF TG_OP='UPDATE' AND OLD.status='Active' THEN RAISE EXCEPTION 'Active account identity is immutable; add another code' USING ERRCODE='23514';END IF;
  IF NEW.status='Active' AND current_user='erp_api' AND (erp_private.actor()).category_code IS DISTINCT FROM 'PARTNER' THEN RAISE EXCEPTION 'Partner approval required' USING ERRCODE='42501';END IF;
 ELSIF TG_TABLE_NAME='sales_reconciliations' AND TG_OP='UPDATE' THEN
  IF OLD.status='Locked' THEN RAISE EXCEPTION 'Approved reconciliation is immutable' USING ERRCODE='23514';END IF;
  IF (NEW.project_id,NEW.review_type,NEW.starts_on,NEW.ends_on,NEW.prepared_by) IS DISTINCT FROM (OLD.project_id,OLD.review_type,OLD.starts_on,OLD.ends_on,OLD.prepared_by) THEN RAISE EXCEPTION 'Reconciliation identity is immutable' USING ERRCODE='23514';END IF;
  IF OLD.status='Submitted' AND NEW.status NOT IN ('Locked','Returned') THEN RAISE EXCEPTION 'Reviewer must return the submitted reconciliation' USING ERRCODE='23514';END IF;
 END IF;RETURN NEW;
END;$$;
DO $$DECLARE r record;BEGIN
 FOR r IN SELECT * FROM (VALUES ('account_catalog','code'),('accounting_policies','client_id'),('sales_reconciliations','reconciliation_id')) AS x(tbl,key) LOOP
 EXECUTE format('ALTER TABLE erp_private.%I ENABLE ROW LEVEL SECURITY',r.tbl);EXECUTE format('ALTER TABLE erp_private.%I FORCE ROW LEVEL SECURITY',r.tbl);
 EXECUTE format('CREATE TRIGGER revision BEFORE UPDATE ON erp_private.%I FOR EACH ROW EXECUTE FUNCTION erp_private.touch_revision()',r.tbl);
 EXECUTE format('CREATE TRIGGER audit AFTER INSERT OR UPDATE ON erp_private.%I FOR EACH ROW EXECUTE FUNCTION erp_private.log_change(%L)',r.tbl,r.key);
 EXECUTE format('CREATE TRIGGER no_delete BEFORE DELETE ON erp_private.%I FOR EACH ROW EXECUTE FUNCTION erp_private.reject_delete()',r.tbl);
 END LOOP;
END;$$;
CREATE TRIGGER control_guard BEFORE INSERT OR UPDATE ON erp_private.account_catalog FOR EACH ROW EXECUTE FUNCTION erp_private.accounting_control_guard();
CREATE TRIGGER control_guard BEFORE UPDATE ON erp_private.sales_reconciliations FOR EACH ROW EXECUTE FUNCTION erp_private.accounting_control_guard();
ALTER TABLE erp_private.sales_review_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE erp_private.sales_review_versions FORCE ROW LEVEL SECURITY;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON erp_private.sales_review_versions FOR EACH ROW EXECUTE FUNCTION erp_private.reject_audit_change();
CREATE POLICY catalog_read ON erp_private.account_catalog FOR SELECT TO erp_api USING((erp_private.actor()).staff_id IS NOT NULL);
CREATE POLICY catalog_add ON erp_private.account_catalog FOR INSERT TO erp_api WITH CHECK(erp_private.is_leader());
CREATE POLICY catalog_update ON erp_private.account_catalog FOR UPDATE TO erp_api USING(erp_private.is_leader()) WITH CHECK(erp_private.is_leader());
CREATE POLICY accounting_read ON erp_private.accounting_policies FOR SELECT TO erp_api USING(erp_private.client_allowed(client_id));
CREATE POLICY accounting_write ON erp_private.accounting_policies FOR ALL TO erp_api USING(erp_private.is_leader() AND erp_private.client_allowed(client_id)) WITH CHECK(erp_private.is_leader() AND erp_private.client_allowed(client_id));
CREATE POLICY reconciliation_read ON erp_private.sales_reconciliations FOR SELECT TO erp_api USING(erp_private.project_allowed(project_id) AND (erp_private.actor()).category_code<>'INTERN');
CREATE POLICY reconciliation_write ON erp_private.sales_reconciliations FOR ALL TO erp_api USING(erp_private.project_allowed(project_id) AND (prepared_by=(erp_private.actor()).staff_id OR erp_private.project_editor())) WITH CHECK(erp_private.project_allowed(project_id) AND (erp_private.actor()).category_code<>'INTERN');
CREATE POLICY versions_read ON erp_private.sales_review_versions FOR SELECT TO erp_api USING(erp_private.project_allowed(project_id) AND (erp_private.actor()).category_code<>'INTERN');
CREATE POLICY versions_add ON erp_private.sales_review_versions FOR INSERT TO erp_api WITH CHECK(erp_private.project_allowed(project_id) AND created_by=(erp_private.actor()).staff_id AND (erp_private.actor()).category_code<>'INTERN');
GRANT SELECT,INSERT,UPDATE ON erp_private.account_catalog,erp_private.accounting_policies,erp_private.sales_reconciliations TO erp_api;
GRANT SELECT,INSERT ON erp_private.sales_review_versions TO erp_api;
REVOKE ALL ON erp_private.account_catalog,erp_private.accounting_policies,erp_private.sales_reconciliations,erp_private.sales_review_versions FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION erp_private.accounting_row_guard(),erp_private.split_totals_guard(),erp_private.accounting_control_guard() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION erp_private.accounting_row_guard(),erp_private.split_totals_guard(),erp_private.accounting_control_guard() TO erp_api;

-- Weekly cumulative reviews are separate from operational Monday-Sunday tasks.
CREATE FUNCTION erp_private.generate_vat_mtd_reviews(through_at timestamptz DEFAULT now()) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE r record;m date;s date;e date;n integer:=0;
BEGIN
 FOR r IN SELECT ps.*,p.client_id FROM erp_private.project_schedules ps JOIN erp_private.projects p USING(project_id)
 WHERE ps.enabled AND ps.deleted_at IS NULL AND p.deleted_at IS NULL AND p.status='Active' AND ps.frequency LIKE '%Weekly%' AND 'VAT'=ANY(ps.obligations)
 LOOP
 FOR m IN SELECT d::date FROM generate_series(greatest(r.starts_on,r.effective_from,((through_at AT TIME ZONE 'Africa/Nairobi')::date-370))::timestamp,(through_at AT TIME ZONE 'Africa/Nairobi')::date::timestamp,interval '1 day') d
 WHERE extract(isodow FROM d)=1 AND (d::date+time '03:00') AT TIME ZONE 'Africa/Nairobi'<=through_at AND d::date<=r.ends_on+1 LOOP
 e:=m-1;s:=date_trunc('month',e)::date;
 IF e<r.starts_on THEN CONTINUE;END IF;
 INSERT INTO erp_private.sales_reconciliations(project_id,review_type,starts_on,ends_on,prepared_by,inputs) VALUES(r.project_id,'Weekly',s,e,r.assigned_to,jsonb_build_object('generated_at',through_at,'provisional',true)) ON CONFLICT DO NOTHING;
 IF FOUND THEN n:=n+1;END IF;
 END LOOP;END LOOP;RETURN n;
END;$$;
REVOKE ALL ON FUNCTION erp_private.generate_vat_mtd_reviews(timestamptz) FROM PUBLIC,anon,authenticated,service_role,erp_api;
SELECT cron.schedule('pcl-vat-mtd-reviews','0 * * * *','select erp_private.generate_vat_mtd_reviews();');

CREATE OR REPLACE FUNCTION erp_private.tax_period_open(p uuid,s date,e date) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT NOT EXISTS(SELECT 1 FROM erp_private.tax_cases c WHERE c.project_id=p AND c.status IN ('Submitted','Locked','Filed') AND c.starts_on<=e AND c.ends_on>=s)
 AND NOT EXISTS(SELECT 1 FROM erp_private.sales_reconciliations r WHERE r.project_id=p AND r.review_type='Monthly' AND r.status IN ('Submitted','Locked') AND r.starts_on<=e AND r.ends_on>=s)
$$;
